#include "KS/SRC/stringx.h"

class script_instance { public: const stringx& get_name() const; };
class script_executable { public: const stringx& get_fullname() const; };
class vm_thread {
public:
    script_instance* get_instance() const;
    script_executable* get_executable() const;
};
class vm_stack {
    int salloc; char* buffer; char* SP; vm_thread* my_thread;
public:
    vm_thread* get_thread() const { return my_thread; }
    bool push(const char* src, int n);
};
class script_library_class {
public:
    class function {
    public:
        enum entry_t { FIRST_ENTRY, RECALL_ENTRY };
        virtual bool operator()(vm_stack& stack, entry_t entry) { return true; }
    };
};
typedef void* vm_num_list_t;
extern vm_num_list_t create_script_num_list();
extern void error(const stringx& message);
#define SLF_RETURN if (!stack.push((char*)&result,sizeof(result)) ) error( stack.get_thread()->get_instance()->get_name() + ": stack overflow in " + stack.get_thread()->get_executable()->get_fullname() )
#define SLF_DONE return true
class slf_create_num_list_t : public script_library_class::function {
public:
    virtual bool operator ()(vm_stack &stack, entry_t entry)
    {
        vm_num_list_t result = create_script_num_list();
    SLF_RETURN;
    SLF_DONE;
    }
};
